alter table public.ps_workouts drop constraint ps_workouts_check;
alter table public.ps_workouts add constraint ps_workouts_check check((source_type='youtube' and video_url ~ '^https://(www[.]|m[.])?(youtube[.]com/|youtu[.]be/)' and video_path is null) or (source_type='upload' and video_path is not null and video_url is null));
create or replace function public.ps_chat_avatar_visible(p_path text) returns boolean language sql stable security definer set search_path='' as $$
select auth.uid() is not null and exists(select 1 from public.ps_profiles p where p.avatar_path=p_path and p_path like p.id::text||'/avatar-%' and (p.id=auth.uid() or exists(select 1 from public.ps_community_messages m where m.author_id=p.id) or exists(select 1 from public.ps_direct_threads t where p.id in(t.client_id,t.coach_id) and public.ps_thread_access(t.id)))) $$;
create or replace function public.ps_chat_people(p_ids uuid[]) returns table(id uuid,full_name text,avatar_path text) language sql stable security definer set search_path='' as $$
select p.id,p.full_name,case when p.avatar_path like p.id::text||'/avatar-%' then p.avatar_path end from public.ps_profiles p where auth.uid() is not null and p.id=any(p_ids) and (p.id=auth.uid() or exists(select 1 from public.ps_community_messages m where m.author_id=p.id) or exists(select 1 from public.ps_direct_threads t where p.id in(t.client_id,t.coach_id) and public.ps_thread_access(t.id))) $$;
